/* The core clobbers every general register. Calling it through an
   asm statement with an explicit clobber list makes GCC spill its
   live loop state into the stack frame around it; a plain call lets
   the compiler keep counters in registers the core overwrites. */
static inline int duco_rounds_asm(void) {
  register uint8_t hit asm("r24");
  __asm__ volatile ("call duco_rounds_core"
      : "=r"(hit)
      : : "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15", "r16", "r17", "r18", "r19", "r20", "r21", "r22", "r23", "r25", "r26", "r27", "r30", "r31");
  return hit;
}
